class MemoryOverflow(ValueError):
    pass


class MemoryBlock:
    def __init__(self, label, value="", limit=200):
        self.label = label
        self.value = value
        self.limit = limit

    def _commit(self, candidate):
        if len(candidate) > self.limit:
            raise MemoryOverflow(
                f"core block {self.label!r} over budget "
                f"({len(candidate)}/{self.limit}) - must evict to archival")
        self.value = candidate

    def append(self, text):
        self._commit((self.value + "\n" + text).strip())

    def replace(self, old, new):
        if old not in self.value:
            raise ValueError(f"{old!r} is not in core block {self.label!r}")
        self._commit(self.value.replace(old, new))


class Agent:
    def __init__(self, blocks=None, limit=200):
        self.core = {label: MemoryBlock(label, value, limit)
                     for label, value in (blocks or {}).items()}
        self.archival = []
        self.recall = []

    def core_memory_append(self, label, text):
        self.core[label].append(text)

    def core_memory_replace(self, label, old, new):
        self.core[label].replace(old, new)

    def archival_memory_insert(self, text):
        self.archival.append(text)

    @staticmethod
    def _score(query, text):
        return len(set(query.lower().split()) & set(text.lower().split()))

    def archival_memory_search(self, query, k=2):
        scored = [(self._score(query, text), index, text)
                  for index, text in enumerate(self.archival)]
        scored = [row for row in scored if row[0] > 0]
        scored.sort(key=lambda row: (-row[0], row[1]))
        return [text for _, _, text in scored[:max(0, k)]]

    def message(self, role, content):
        self.recall.append({"role": role, "content": content})

    def conversation_search(self, query, k=2):
        scored = [(self._score(query, entry["content"]), index, entry)
                  for index, entry in enumerate(self.recall)]
        scored = [row for row in scored if row[0] > 0]
        scored.sort(key=lambda row: (-row[0], row[1]))
        return [entry for _, _, entry in scored[:max(0, k)]]

    def remember(self, label, text):
        try:
            self.core_memory_append(label, text)
        except MemoryOverflow:
            self.archival_memory_insert(text)
            return "archival"
        return "core"

    def context_window(self):
        return "\n".join(f"[{block.label}] {block.value}"
                          for block in self.core.values())
